-- **`total_size_bytes` 는 0 으로 세운다 — 손으로 합계를 넣지 않는다.** 아래 `d3_file` INSERT 가
-- 트리거(`0009` `sync_dataset_total_size`)로 더해 DSA1 100 · DSA2 200 · DSB1 300 이 된다.
-- 여기 합계를 적으면 **두 번 센다** — 실제로 그렇게 200 == 100 red 가 났다
-- (`tests/test_dataset_detail.py::test_files_cell_says_count_and_total_size_only`).
-- `file_count` 와 같은 규율이다(아래 주석). ⚠ 순서가 뜻이다 — autometa 행이 파일보다 **앞**에 서야
-- 트리거가 더할 자리가 있다(없는 데이터셋은 트리거가 건너뛴다).
INSERT INTO d3_dataset_autometa (dataset_id, lab_id, format, variables, crs, total_size_bytes) VALUES
  ('0000000000000000000000DSA1', '0000000000000000000000000A', 'CSV',    '{강우량}', 'EPSG:5179', 0),
  ('0000000000000000000000DSA2', '0000000000000000000000000A', 'NetCDF', '{강우량}', 'EPSG:5179', 0),
  ('0000000000000000000000DSB1', '0000000000000000000000000B', 'CSV',    '{토지피복}', 'EPSG:5179', 0);

-- 파일. **`d3_dataset.file_count` 는 여기서 손으로 넣지 않는다** — 트리거가 유지한다 (㊼).
-- 손으로 적으면 시드가 트리거를 검사하는 대신 트리거를 흉내 내게 된다.
-- **축을 명시한다** (`0004` · `〈66〉`). 기준 격자 파일은 `carries_lat`·`carries_lon` 중
-- 최소 하나가 true 여야 하고 본체는 둘 다 false 여야 한다 — 안 적으면 시드가 들어가지 않는다.
-- `a1-grid.nc` 를 **결합축**(둘 다 true)으로 둔 것은 이 파일이 픽스처라서다:
--   실물 `.nc` 격자는 한 파일에 `lat`·`lon` 을 다 담고(`DATA-REFERENCE §1` · `〈66〉`),
--   결합축 1건이면 이 데이터셋의 `hasReferenceGridFile` 이 종전과 똑같이 true 로 남는다.
--   **측정된 값이 아니라 픽스처 저작이다** — 실데이터의 축은 서버가 파일에서 판별한다(`〈63〉-㉰`).
INSERT INTO d3_file (id, lab_id, dataset_id, kind, file_name, size_bytes, storage_key, carries_lat, carries_lon) VALUES
  ('00000000000000000000000FA1', '0000000000000000000000000A', '0000000000000000000000DSA1', '본체',            'a1-body.csv', 50, 'k/a1',  false, false),
  ('00000000000000000000000FA2', '0000000000000000000000000A', '0000000000000000000000DSA1', '기준 격자 파일', 'a1-grid.nc',  50, 'k/a1g', true,  true),
  ('00000000000000000000000FA3', '0000000000000000000000000A', '0000000000000000000000DSA2', '본체',            'a2-body.nc', 200, 'k/a2',  false, false),
  ('00000000000000000000000FB1', '0000000000000000000000000B', '0000000000000000000000DSB1', '본체',            'b1-body.csv', 300, 'k/b1',  false, false);

-- 접근 상태. DSB1 은 **일부러 행이 없다** — 연구실 기본값(열림)으로 떨어지는 COALESCE 경로를 함께 태운다.
